def get_grade(score):
    """
    Takes a student's score as input and outputs their corresponding grade.

    :param score: int, the student's score between 0 and 100
    :return: str, the student's grade (A, B, C, D, or F) or 'Invalid score' if the score is not within the range
    """
    if not isinstance(score, int) or score < 0 or score > 100:
        return 'Invalid score'

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

# Example usage:
score = int(input("Enter a student's score between 0 and 100: "))
grade = get_grade(score)

if grade != 'Invalid score':
    print(f"The student's grade is {grade}.")
else:
    print("Invalid score. Please enter a score between 0 and 100.")
